diff --git a/src/devicename.cpp b/src/devicename.cpp
new file mode 100644
index 00000000..6c0d7ed9
--- /dev/null
+++ b/src/devicename.cpp
@@ -0,0 +1,112 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include "devicename.h"
+
+#include <PulseAudioQt/Card>
+#include <PulseAudioQt/CardPort>
+#include <PulseAudioQt/Context>
+#include <PulseAudioQt/Port>
+
+using namespace Qt::Literals::StringLiterals;
+
+static PulseAudioQt::Card *cardForDevice(const PulseAudioQt::Device *device)
+{
+    const auto cards = PulseAudioQt::Context::instance()->cards();
+    for (PulseAudioQt::Card *card : cards) {
+        if (card->index() == device->cardIndex()) {
+            return card;
+        }
+    }
+    return nullptr;
+}
+
+DeviceName::DeviceName(QObject *parent)
+    : QObject(parent)
+{
+    auto context = PulseAudioQt::Context::instance();
+    connect(context, &PulseAudioQt::Context::cardAdded, this, &DeviceName::update);
+    connect(context, &PulseAudioQt::Context::cardRemoved, this, &DeviceName::update);
+}
+
+PulseAudioQt::Device *DeviceName::device() const
+{
+    return m_device;
+}
+
+void DeviceName::setDevice(PulseAudioQt::Device *device)
+{
+    if (m_device == device) {
+        return;
+    }
+    if (m_device) {
+        disconnect(m_device, nullptr, this, nullptr);
+    }
+    m_device = device;
+    if (m_device) {
+        connect(m_device, &PulseAudioQt::Device::cardIndexChanged, this, &DeviceName::update);
+        connect(m_device, &PulseAudioQt::Device::portsChanged, this, &DeviceName::update);
+        connect(m_device, &PulseAudioQt::Device::activePortIndexChanged, this, &DeviceName::update);
+        connect(m_device, &PulseAudioQt::Device::descriptionChanged, this, &DeviceName::update);
+        connect(m_device, &PulseAudioQt::Device::pulsePropertiesChanged, this, &DeviceName::update);
+    }
+    Q_EMIT deviceChanged();
+    update();
+}
+
+QString DeviceName::connectedDisplay() const
+{
+    return m_connectedDisplay;
+}
+
+QString DeviceName::connectedDisplay(const PulseAudioQt::Device *device)
+{
+    if (!device) {
+        return {};
+    }
+
+    // Renaming a device sets its nick to the new name too; the user's name wins
+    if (device->pulseProperties().value(u"node.nick"_s).toString() == device->description()) {
+        return {};
+    }
+
+    const auto ports = device->ports();
+    const PulseAudioQt::Card *card = cardForDevice(device);
+    if (!card || device->activePortIndex() >= quint32(ports.size())) {
+        return {};
+    }
+
+    const QString portName = ports.at(device->activePortIndex())->name();
+    const auto cardPorts = card->ports();
+    for (const PulseAudioQt::CardPort *port : cardPorts) {
+        if (port->name() == portName) {
+            return port->properties().value(u"device.product.name"_s).toString();
+        }
+    }
+    return {};
+}
+
+void DeviceName::update()
+{
+    for (const auto &connection : std::as_const(m_cardConnections)) {
+        disconnect(connection);
+    }
+    m_cardConnections.clear();
+
+    if (PulseAudioQt::Card *card = m_device ? cardForDevice(m_device) : nullptr) {
+        m_cardConnections << connect(card, &PulseAudioQt::Card::portsChanged, this, &DeviceName::update);
+        const auto cardPorts = card->ports();
+        for (PulseAudioQt::CardPort *port : cardPorts) {
+            m_cardConnections << connect(port, &PulseAudioQt::PulseObject::propertiesChanged, this, &DeviceName::update);
+        }
+    }
+
+    const QString connectedDisplay = DeviceName::connectedDisplay(m_device);
+    if (m_connectedDisplay != connectedDisplay) {
+        m_connectedDisplay = connectedDisplay;
+        Q_EMIT connectedDisplayChanged();
+    }
+}
diff --git a/src/devicename.h b/src/devicename.h
new file mode 100644
index 00000000..924f5e03
--- /dev/null
+++ b/src/devicename.h
@@ -0,0 +1,43 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#pragma once
+
+#include <QObject>
+#include <QPointer>
+#include <QString>
+#include <qqmlregistration.h>
+
+#include <PulseAudioQt/Device>
+
+class DeviceName : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+    Q_PROPERTY(PulseAudioQt::Device *device READ device WRITE setDevice NOTIFY deviceChanged)
+    // Name of the monitor or receiver connected to the device's active HDMI/DisplayPort port, as reported by its EDID
+    Q_PROPERTY(QString connectedDisplay READ connectedDisplay NOTIFY connectedDisplayChanged)
+
+public:
+    explicit DeviceName(QObject *parent = nullptr);
+
+    PulseAudioQt::Device *device() const;
+    void setDevice(PulseAudioQt::Device *device);
+    QString connectedDisplay() const;
+
+    static QString connectedDisplay(const PulseAudioQt::Device *device);
+
+Q_SIGNALS:
+    void deviceChanged();
+    void connectedDisplayChanged();
+
+private:
+    void update();
+
+    QPointer<PulseAudioQt::Device> m_device;
+    QString m_connectedDisplay;
+    QList<QMetaObject::Connection> m_cardConnections;
+};
